-- Dalaran customer greetings belong to the shopkeeper, addressed to a player.
-- These friendly OOC-LOS events previously reacted to nearby NPCs/critters too.
-- With target=ACTION_INVOKER and useTalkTarget=0, a creature invoker becomes
-- the speaker, requesting the shopkeeper's group from unrelated creature_text.
-- Enable the existing playerOnly event parameter; retain text, target, cooldown,
-- event/action semantics and real/bot player greetings. Full-row numeric guards
-- preserve modified events. Do not apply to unrelated scripted conversations.
UPDATE smart_scripts SET event_param5=1 WHERE entryorguid=28347 AND source_type=0 AND id=1 AND link=0 AND event_type=10 AND event_phase_mask=0 AND event_chance=100 AND event_flags=0 AND event_param1=1 AND event_param2=20 AND event_param3=30000 AND event_param4=60000 AND action_type=1 AND action_param1=5 AND action_param2=0 AND action_param3=0 AND action_param4=0 AND action_param5=0 AND action_param6=0 AND target_type=7 AND target_param1=0 AND target_param2=0 AND target_param3=0 AND target_x=0 AND target_y=0 AND target_z=0 AND target_o=0 AND event_param5=0 AND target_param4=0;
